def romanToInt(self, s: str) -> int:
    value = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    prev = 0
    for c in reversed(s):
        cur = value[c]
        if cur < prev:
            total -= cur
        else:
            total += cur
        prev = cur
    return total

